#!/usr/bin/env bun
// Compiles src/tui.tsx to dist/tui.js, the file the `./tui` export points at for npm installs.
//
// Why a build: OpenCode's Solid transform skips any file under node_modules (solid-plugin.js
// `sourceFilter`), so a published src/tui.tsx would load as plain Bun JSX and break. The same
// Solid preset OpenCode uses (babel-preset-solid, generate "universal", moduleName "@opentui/solid")
// runs here instead, once, before publish. The output keeps literal `from "solid-js"` and
// `from "@opentui/solid"` imports, which OpenCode's runtime plugin rewrites to its own copies.
// Relative imports point at ../src/ because the output lives in dist/.
//
//   bun run build:tui
import { transformAsync } from "@babel/core"
// @ts-expect-error - Types not important (same as the host, packages/tui in OpenCode).
import ts from "@babel/preset-typescript"
// @ts-expect-error - Types not important.
import solid from "babel-preset-solid"
import { mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const root = join(import.meta.dir, "..", "..")
const source = join(root, "src", "tui.tsx")
const target = join(root, "dist", "tui.js")

// Import and export sources in dist/ point one level up, into src/. Only "./" specifiers move.
const relativeToSrc = () => ({
  visitor: {
    "ImportDeclaration|ExportNamedDeclaration|ExportAllDeclaration"(path: { node: { source?: { value: string } } }) {
      const node = path.node.source
      if (node?.value.startsWith("./")) node.value = `../src/${node.value.slice(2)}`
    },
  },
})

const code = readFileSync(source, "utf8")
const result = await transformAsync(code, {
  filename: source,
  configFile: false,
  babelrc: false,
  plugins: [relativeToSrc],
  presets: [[solid, { moduleName: "@opentui/solid", generate: "universal" }], [ts]],
})
if (!result?.code) throw new Error(`build:tui: babel produced no output for ${source}`)

mkdirSync(join(root, "dist"), { recursive: true })
writeFileSync(target, `// Generated by .github/scripts/build-tui.ts from src/tui.tsx. Do not edit.\n${result.code}\n`)
console.log(`built ${target} (${result.code.length} bytes)`)
